import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Releases — Advanced Features & Customization","description":"","frontmatter":{},"headers":[],"relativePath":"releases-03-advanced-and-customization.md","filePath":"releases-03-advanced-and-customization.md"}'),r={name:"releases-03-advanced-and-customization.md"};function i(n,e,l,d,u,c){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="releases-—-advanced-features-customization" tabindex="-1">Releases — Advanced Features &amp; Customization <a class="header-anchor" href="#releases-—-advanced-features-customization" aria-label="Permalink to &quot;Releases — Advanced Features &amp; Customization&quot;">​</a></h1><p><em>Forecast mode strategy, Release Notes best practices, and integration behavior</em></p><hr><h2 id="getting-the-most-from-forecast-mode" tabindex="-1">Getting the Most from Forecast Mode <a class="header-anchor" href="#getting-the-most-from-forecast-mode" aria-label="Permalink to &quot;Getting the Most from Forecast Mode&quot;">​</a></h2><p>Forecast mode is one of the most underused features in the Releases module. Used well, it lets you be a proactive communicator rather than a reactive one — showing stakeholders where things are headed, not just where they are today.</p><h3 id="when-to-use-forecast" tabindex="-1">When to use Forecast <a class="header-anchor" href="#when-to-use-forecast" aria-label="Permalink to &quot;When to use Forecast&quot;">​</a></h3><ul><li>Before a stakeholder update or leadership check-in, to show anticipated progress at a future date</li><li>When a delivery date is at risk and you need to communicate a revised expectation without misrepresenting current reality</li><li>For &quot;what if&quot; planning — exploring what the board looks like if certain Features slip or accelerate</li></ul><h3 id="how-forecast-and-actual-coexist" tabindex="-1">How Forecast and Actual coexist <a class="header-anchor" href="#how-forecast-and-actual-coexist" aria-label="Permalink to &quot;How Forecast and Actual coexist&quot;">​</a></h3><p>Forecast positions are saved separately from actual status and persist until manually cleared. This means:</p><ul><li>You can freely move cards in Forecast without worrying about corrupting real data</li><li>Your forecast positions are remembered between sessions — you don&#39;t need to rebuild them each time</li><li>Toggling to Actual always shows the true state; toggling back to Forecast restores your last forecast positions</li></ul><h3 id="exporting-forecast-views" tabindex="-1">Exporting Forecast views <a class="header-anchor" href="#exporting-forecast-views" aria-label="Permalink to &quot;Exporting Forecast views&quot;">​</a></h3><p>Both Actual and Forecast views can be exported as PNG or PPT. A common pattern is to export both and share them side by side — &quot;here&#39;s where we are today, and here&#39;s where we expect to be by [date].&quot;</p><hr><h2 id="writing-effective-release-notes" tabindex="-1">Writing Effective Release Notes <a class="header-anchor" href="#writing-effective-release-notes" aria-label="Permalink to &quot;Writing Effective Release Notes&quot;">​</a></h2><p>Release Notes are one of the few places in Lodestone where AI generates content not tied to a single Feature. Because they aggregate multiple Features for a specific audience, a few practices make a significant difference in output quality.</p><h3 id="be-selective-about-which-features-to-include" tabindex="-1">Be selective about which Features to include <a class="header-anchor" href="#be-selective-about-which-features-to-include" aria-label="Permalink to &quot;Be selective about which Features to include&quot;">​</a></h3><p>Not every Feature in a Release needs to appear in Release Notes. Focus on Features that are completed or nearly completed, and that are meaningful to the target audience. Including in-progress or low-visibility Features adds noise.</p><h3 id="match-the-audience-setting-to-the-reader" tabindex="-1">Match the audience setting to the reader <a class="header-anchor" href="#match-the-audience-setting-to-the-reader" aria-label="Permalink to &quot;Match the audience setting to the reader&quot;">​</a></h3><ul><li><strong>Internal</strong> notes use product and team language — appropriate for CS, sales, marketing, and leadership</li><li><strong>External</strong> notes use customer-facing language — suitable for changelogs, customer emails, or partner updates</li></ul><p>Choosing the wrong audience setting produces notes that need significant editing. Get this right upfront.</p><h3 id="regenerate-deliberately" tabindex="-1">Regenerate deliberately <a class="header-anchor" href="#regenerate-deliberately" aria-label="Permalink to &quot;Regenerate deliberately&quot;">​</a></h3><p>Regenerating Release Notes overwrites the previous version. If you&#39;ve edited the AI output and want to keep those edits, copy or export the notes before regenerating. Treat regeneration as a fresh start, not a refinement.</p><h3 id="use-release-notes-as-a-source-for-other-communications" tabindex="-1">Use Release Notes as a source for other communications <a class="header-anchor" href="#use-release-notes-as-a-source-for-other-communications" aria-label="Permalink to &quot;Use Release Notes as a source for other communications&quot;">​</a></h3><p>Release Notes output is designed to be reused. Common downstream uses:</p><ul><li>Paste into a customer email</li><li>Use as the basis for a changelog entry</li><li>Include in an internal sprint review or stakeholder update</li><li>Feed into a company blog post or social post (via the Documents module for the individual Features)</li></ul><hr><h2 id="using-multiple-releases-for-the-same-work" tabindex="-1">Using Multiple Releases for the Same Work <a class="header-anchor" href="#using-multiple-releases-for-the-same-work" aria-label="Permalink to &quot;Using Multiple Releases for the Same Work&quot;">​</a></h2><p>Because Features can belong to multiple Releases simultaneously, you can maintain different Release views without duplicating data. Common patterns:</p><h3 id="milestone-ongoing" tabindex="-1">Milestone + ongoing <a class="header-anchor" href="#milestone-ongoing" aria-label="Permalink to &quot;Milestone + ongoing&quot;">​</a></h3><p>One Release tracks a specific milestone or launch date; a second tracks the ongoing backlog. The same Features can appear in both.</p><h3 id="by-audience" tabindex="-1">By audience <a class="header-anchor" href="#by-audience" aria-label="Permalink to &quot;By audience&quot;">​</a></h3><p>One Release view structured for engineering status updates; another structured for executive or customer-facing communication. The same Features appear in both, but you share different exports with different audiences.</p><h3 id="overlapping-timelines" tabindex="-1">Overlapping timelines <a class="header-anchor" href="#overlapping-timelines" aria-label="Permalink to &quot;Overlapping timelines&quot;">​</a></h3><p>For Features that span multiple quarters, they can appear in multiple quarterly Releases simultaneously, with their status updating consistently across all of them.</p><hr><h2 id="releases-and-jira-integration" tabindex="-1">Releases and JIRA Integration <a class="header-anchor" href="#releases-and-jira-integration" aria-label="Permalink to &quot;Releases and JIRA Integration&quot;">​</a></h2><p>If your team has the JIRA integration active, delivery status flows into Releases automatically. A few things to understand about how this works:</p><ul><li>Status changes in JIRA update Feature status in Lodestone, which updates the Feature card on the Release board</li><li>The mapping between JIRA statuses and Lodestone status stages is configured in Settings &gt; Integrations — if a Feature&#39;s status isn&#39;t updating as expected, check the status mapping first</li><li>Lodestone is the communication layer; JIRA is the execution layer. The integration keeps them in sync so you don&#39;t have to update both manually</li></ul><p>For teams using JIRA, the Release board effectively becomes a live view of delivery progress without any manual status updates on the Lodestone side.</p><hr><h2 id="releases-vs-roadmaps-a-quick-reference" tabindex="-1">Releases vs Roadmaps: A Quick Reference <a class="header-anchor" href="#releases-vs-roadmaps-a-quick-reference" aria-label="Permalink to &quot;Releases vs Roadmaps: A Quick Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Roadmap</th><th>Release</th></tr></thead><tbody><tr><td>Primary question</td><td>WHAT and WHY</td><td>WHEN and HOW IS IT GOING</td></tr><tr><td>Time orientation</td><td>Forward-looking</td><td>Current state + near-term</td></tr><tr><td>Visual format</td><td>Sunburst chart</td><td>Kanban board</td></tr><tr><td>AI content in export</td><td>Yes (PPT)</td><td>No</td></tr><tr><td>HTML shareable export</td><td>Yes</td><td>Yes</td></tr><tr><td>Typical audience</td><td>Leadership, sales, customers</td><td>CS, ops, team, stakeholders</td></tr><tr><td>Updated cadence</td><td>When priorities shift</td><td>Regularly as work progresses</td></tr></tbody></table><hr><p><em>Next: Troubleshooting &amp; FAQs — common issues with status sync, Forecast mode, and Release Notes.</em></p>',44)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
